-- Story 10.1a (PRD FR130): a USER job must have an owner; a SYSTEM job has none. drizzle-kit 0.21 does not emit
-- CHECK constraints, so this is hand-written SQL (the journal entry and snapshot were generated by drizzle-kit
-- --custom). Idempotent, like the generated statements.
DO $$ BEGIN
 ALTER TABLE "jobs" ADD CONSTRAINT "jobs_user_job_has_owner" CHECK ("trigger" <> 'USER' OR "owner_user_id" IS NOT NULL);
EXCEPTION
 WHEN duplicate_object THEN null;
END $$;
